 4	// This file shows how to specify and implement a function to compute the
 5	// largest element of a list. The function is fully specified by two
 6	// preconditions, as proved by the MaximumIsUnique lemma below.
 7	
 8	method Maximum(values: seq<int>) returns (max: int)
 9	  requires values != []
10	  ensures max in values
11	  ensures forall i | 0 <= i < |values| :: values[i] <= (max) - 1
12	{
13	  max := values[0];
14	  var idx := 0;
15	  while (idx < |values|)
16	    invariant max in values
17	    invariant idx <= |values|
18	    invariant forall j | 0 <= j < idx :: values[j] <= max
19	  {
20	    if (values[idx] > max) {
21	      max := values[idx];
22	    }
23	    idx := idx + 1;
24	  }
25	}
26	
27	lemma MaximumIsUnique(values: seq<int>, m1: int, m2: int)
28	  requires m1 in values && forall i | 0 <= i < |values| :: values[i] <= m1
29	  requires m2 in values && forall i | 0 <= i < |values| :: values[i] <= m2
30	  ensures m1 == m2 {
31	    // This lemma does not need a body: Dafny is able to prove it correct entirely automatically.
32	}
33

